javascript(/**
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 */
function evaluateEvent({
    api,
    event
}) {
    if (event.payload.selectedTab === "id=analyst_workbench") {
        return {
            event: "Workbench Visited",
            value: {
                Type: "Analyst Workbench",
                Source: "Platform"
            }
        };
    }
    if (event.payload.selectedTab === "id=opportunity_details") {
        return {
            event: "Open improvement opportunity details",
            value: {
                Type: "Opportunity details",
                Source: "Platform"
            }
        };
    }
})

